package dev.veltraph.client.observation.nativeinput;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Exact IEEE bit expectations from the pinned native zero-turn arithmetic; no live pose or source authority. */
final class NativeStationaryPoseArithmeticTest {
 private static void bits(int expected,float value){assertEquals(expected,Float.floatToRawIntBits(value));}
 private static void outcome(NativeStationaryPoseArithmetic.Result r,int firstPitch,int yaw,int secondPitch,int finalYaw,int finalPitch){assertNotNull(r);bits(firstPitch,r.firstPitchArgument());bits(yaw,r.yawArgument());bits(secondPitch,r.secondPitchArgument());bits(finalYaw,r.finalYaw());bits(finalPitch,r.finalPitch());}
 @Test void allSixteenSignedZeroCombinationsHaveExactBits(){int[] zero={0x00000000,0x80000000};double[] delta={0.0D,-0.0D};for(int y=0;y<2;y++)for(int p=0;p<2;p++)for(int dx=0;dx<2;dx++)for(int dy=0;dy<2;dy++){int yaw=y==1&&dx==1?0x80000000:0;int pitch=p==1&&dy==1?0x80000000:0;outcome(NativeStationaryPoseArithmetic.calculate(Float.intBitsToFloat(zero[y]),Float.intBitsToFloat(zero[p]),delta[dx],delta[dy]),pitch,yaw,pitch,yaw,pitch);}}
 @Test void positiveYawOutsideOneTurnIsAssignedWithoutWrapping(){outcome(NativeStationaryPoseArithmetic.calculate(721.25F,12.5F,0D,0D),0x41480000,0x44345000,0x41480000,0x44345000,0x41480000);}
 @Test void negativeYawOutsideOneTurnIsAssignedWithoutWrapping(){outcome(NativeStationaryPoseArithmetic.calculate(-721.25F,-12.5F,-0D,-0D),0xc1480000,0xc4345000,0xc1480000,0xc4345000,0xc1480000);}
 @Test void pitchRemainderThenClampIsNotAClampedBeforeValue(){float[][] cases={{721,1},{540,90},{450,90},{361,1},{359,90},{270,90},{181,90},{180,90},{91,90},{90,90},{89,89},{1,1},{-721,-1},{-540,-90},{-450,-90},{-361,-1},{-359,-90},{-270,-90},{-181,-90},{-180,-90},{-91,-90},{-90,-90},{-89,-89},{-1,-1}};for(var c:cases){var r=NativeStationaryPoseArithmetic.calculate(10,c[0],0,0);int expected=Float.floatToRawIntBits(c[1]);outcome(r,Float.floatToRawIntBits(c[0]),0x41200000,expected,0x41200000,expected);}}
 @Test void exactPositiveWholeTurnsEndAsPositiveZero(){for(float pitch:new float[]{360F,720F,1080F})outcome(NativeStationaryPoseArithmetic.calculate(0,pitch,-0D,-0D),Float.floatToRawIntBits(pitch),0,0,0,0);}
 @Test void exactNegativeWholeTurnsPreserveNegativeRemainderZero(){for(float pitch:new float[]{-360F,-720F,-1080F})outcome(NativeStationaryPoseArithmetic.calculate(-0.0F,pitch,-0D,0D),Float.floatToRawIntBits(pitch),0x80000000,0x80000000,0x80000000,0x80000000);}
 @Test void largestPositiveFiniteAnglesStayFiniteAndYawUnwrapped(){outcome(NativeStationaryPoseArithmetic.calculate(Float.MAX_VALUE,Float.MAX_VALUE,0,0),0x7f7fffff,0x7f7fffff,0,0x7f7fffff,0);}
 @Test void largestNegativeFinitePitchRetainsNegativeZeroAfterRemainder(){outcome(NativeStationaryPoseArithmetic.calculate(-Float.MAX_VALUE,-Float.MAX_VALUE,-0D,-0D),0xff7fffff,0xff7fffff,0x80000000,0xff7fffff,0x80000000);}
 @Test void positiveSubnormalAndNormalMinimumKeepExactBits(){for(int input:new int[]{0x00000001,0x00000002,0x007fffff,0x00800000})outcome(NativeStationaryPoseArithmetic.calculate(Float.intBitsToFloat(input),Float.intBitsToFloat(input),-0D,0D),input,input,input,input,input);}
 @Test void negativeSubnormalAndNormalMinimumKeepExactBits(){for(int input:new int[]{0x80000001,0x80000002,0x807fffff,0x80800000})outcome(NativeStationaryPoseArithmetic.calculate(Float.intBitsToFloat(input),Float.intBitsToFloat(input),0D,-0D),input,input,input,input,input);}
 @Test void nextFloatAbovePositiveWholeTurnHasExactSmallRemainder(){outcome(NativeStationaryPoseArithmetic.calculate(0,Float.intBitsToFloat(0x43b40001),0,0),0x43b40001,0,0x38000000,0,0x38000000);}
 @Test void nextFloatBelowNegativeWholeTurnHasExactNegativeRemainder(){outcome(NativeStationaryPoseArithmetic.calculate(0,Float.intBitsToFloat(0xc3b40001),0,0),0xc3b40001,0,0xb8000000,0,0xb8000000);}
 @Test void floatJustBeforeWholeTurnIsClampedAfterRemainder(){outcome(NativeStationaryPoseArithmetic.calculate(0,Float.intBitsToFloat(0x43b3ffff),0,0),0x43b3ffff,0,0x42b40000,0,0x42b40000);outcome(NativeStationaryPoseArithmetic.calculate(0,Float.intBitsToFloat(0xc3b3ffff),0,0),0xc3b3ffff,0,0xc2b40000,0,0xc2b40000);}
 @Test void pitchAroundNinetyUsesExactFloatBoundary(){outcome(NativeStationaryPoseArithmetic.calculate(0,Float.intBitsToFloat(0x42b40001),0,0),0x42b40001,0,0x42b40000,0,0x42b40000);outcome(NativeStationaryPoseArithmetic.calculate(0,Float.intBitsToFloat(0xc2b40001),0,0),0xc2b40001,0,0xc2b40000,0,0xc2b40000);}
 @Test void nanBeforeValuesCannotBecomeArithmeticProof(){for(int raw:new int[]{0x7fc00000,0x7fc12345,0xffc12345}){float nan=Float.intBitsToFloat(raw);assertNull(NativeStationaryPoseArithmetic.calculate(nan,0,0,0));assertNull(NativeStationaryPoseArithmetic.calculate(0,nan,0,0));}}
 @Test void eitherInfiniteBeforeValueIsRefused(){for(float bad:new float[]{Float.POSITIVE_INFINITY,Float.NEGATIVE_INFINITY}){assertNull(NativeStationaryPoseArithmetic.calculate(bad,0,0,0));assertNull(NativeStationaryPoseArithmetic.calculate(0,bad,0,0));}}
 @Test void exactNonzeroDeltaIsRefusedEvenIfItsFloatConversionWouldBeZero(){for(double bad:new double[]{Double.MIN_VALUE,-Double.MIN_VALUE,Double.MIN_NORMAL,-Double.MIN_NORMAL,Float.MIN_VALUE,-Float.MIN_VALUE,1D,-1D,Double.MAX_VALUE,-Double.MAX_VALUE}){assertNull(NativeStationaryPoseArithmetic.calculate(0,0,bad,0));assertNull(NativeStationaryPoseArithmetic.calculate(0,0,0,bad));}}
 @Test void nanOrInfiniteDeltasAreRefused(){for(double bad:new double[]{Double.NaN,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY}){assertNull(NativeStationaryPoseArithmetic.calculate(0,0,bad,0));assertNull(NativeStationaryPoseArithmetic.calculate(0,0,0,bad));}}
 @Test void laterCalculationCannotAlterARetainedBeforeDerivedResult(){var old=NativeStationaryPoseArithmetic.calculate(-0.0F,-0.0F,-0D,-0D);outcome(old,0x80000000,0x80000000,0x80000000,0x80000000,0x80000000);assertNotNull(NativeStationaryPoseArithmetic.calculate(721.25F,361F,0,0));outcome(old,0x80000000,0x80000000,0x80000000,0x80000000,0x80000000);}
}
